def fast_erf(x):
    """Fast erf using lookup table."""
    idx = np.clip((x * 512 + 2048).astype(np.int64), 0, 4095)
    return _ERF_TABLE_4096[idx]

def fast_exp(x):
    """Fast exp using lookup table."""
    idx = np.clip((x * 102.4 + 1024).astype(np.int64), 0, 2047)
    return _EXP_TABLE_2048[idx]

def fast_log(x):
    """Fast log using lookup table."""
    idx = np.clip(((x - 0.001) * 2047 / 19.999).astype(np.int64), 0, 2047)
    return _LOG_TABLE_2048[idx]

def fast_sin(x): return _SIN_TABLE_4096[((x % (2*np.pi)) * 4095/(2*np.pi)).astype(np.int64)]
def fast_cos(x): return _COS_TABLE_4096[((x % (2*np.pi)) * 4095/(2*np.pi)).astype(np.int64)]
def fast_tanh(x):
    idx = np.clip((x * 102.4 + 1024).astype(np.int64), 0, 2047)
    return _TANH_TABLE_2048[idx]
def fast_sigmoid(x):
    idx = np.clip((x * 102.4 + 1024).astype(np.int64), 0, 2047)
    return _SIGMOID_TABLE_2048[idx]


